    exam.setPlans = Object.assign({}, exam.setPlans, {2: {target: 150, label: 'Batches 1–6 · Q001–060'}});
    exam.fullExamQuestionsBySet = Object.assign({}, exam.fullExamQuestionsBySet, {2: 150});
